#!/usr/bin/env bash
# Generated by fmverify. Fetches the solver this layer's proofs are discharged by.
#
# Microsoft.Z3 is not on nuget.org (publishing stopped at 4.12.2 in 2023), so the package
# comes from the official Z3Prover release and lands in .packages/, which NuGet.config adds
# as a source. .packages/ is deliberately NOT committed — this script rebuilds it.
#
# The hash is not a formality. The solver decides whether a proof passes, so a package that
# does not match is refused rather than used.
set -euo pipefail
cd "$(dirname "$0")"

VERSION="5.3.3"
SHA256="3ece54cefce4d58be1ce7c00bcff34b691e8076169cba095a057284bfb0b7822"
URL="https://github.com/Z3Prover/z3/releases/download/z3-5.3.3/Microsoft.Z3.5.3.3.nupkg"
NUPKG=".packages/Microsoft.Z3.${VERSION}.nupkg"

actual_sha() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  else shasum -a 256 "$1" | cut -d' ' -f1
  fi
}

if [ -f "$NUPKG" ] && [ "$(actual_sha "$NUPKG")" = "$SHA256" ]; then
  echo "Solver Microsoft.Z3 $VERSION already present and verified."
  exit 0
fi

mkdir -p .packages
echo "Fetching Microsoft.Z3 $VERSION from $URL"
curl -fsSL -o "$NUPKG" "$URL"

ACTUAL="$(actual_sha "$NUPKG")"
if [ "$ACTUAL" != "$SHA256" ]; then
  rm -f "$NUPKG"
  echo "ERROR: solver package hash mismatch. Refusing to use it." >&2
  echo "  expected $SHA256" >&2
  echo "  actual   $ACTUAL" >&2
  exit 1
fi

echo "Solver Microsoft.Z3 $VERSION fetched and verified."
